            continue
        adjacent = unseen_adjacent_range(
            original, visible_start=quote_start, visible_end=quote_end,
            max_lines=SourceContinuationReader.max_lines,
        )
        if adjacent is None:
            continue
        start, end = adjacent
        target = _read_next_row(
            root, original, line_start=start, line_end=end, reason="inspect_source_context",
        )
        if target is not None:
            return target, original
    return None, None

def unread_lines(start: int, end: int, visible: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Inclusive interval difference; a later quote never hides a gap."""
    if type(start) is not int or type(end) is not int or not 1 <= start <= end:
        raise ValueError("invalid line interval")
    cursor = start
    out = []
    for a, b in sorted(visible):
        if type(a) is not int or type(b) is not int or not 1 <= a <= b:
            raise ValueError("invalid visible interval")
        if b < cursor or a > end:
            continue
        if a > cursor:
            out.append((cursor, a - 1))
        cursor = max(cursor, b + 1)
        if cursor > end:
            break
    if cursor <= end:
        out.append((cursor, end))
    return out

