                "cannot be preserved within the model-visible budget "
                f"({estimated_tokens} > {limit})."
            ],
            recommended_next_action=None, max_tokens=INSUFFICIENT_EVIDENCE_MAX_TOKENS,
        ), snapshot
    return payload, snapshot

