def prepare_reference_probe(probe, *, candidate, evidence_text: str):
    """Verify current source/occurrence against prepared snapshot; pure, no I/O.

    Serialized internal dictionaries are validated, never granted authority by
    their Python type or an incoming qualified/trusted flag. Trace bindings are
    recomputed; the application-owned raw source window supplies the evidence.
    """
    from dataclasses import asdict
    from .query_terms import documentation_query_terms, query_constraint_roles
    from .technical_tokens import technical_term_pattern
    result = dict(probe)
    result.pop("bound_subject_context", None)
    source = candidate or {}
    root = source.get("_reference_root_plan")
    if not isinstance(root, dict):
        if source.get("_reference_evidence") or probe.get("reference_bindings"):
            return result, "missing_reference_plan"
        return result, None  # existing strict local policy, no invented owner
    evidence = source.get("_reference_evidence")
    if not isinstance(evidence, dict) or evidence.get("schema_version") != 1:
        return result, "missing_source_reference_evidence"
    identity = evidence.get("source") or {}
    scope = identity.get("scope") or {}
    if not scope.get("project_id") or not scope.get("snapshot_id") or not _valid_reference_plan(root, scope):
        return result, "reference_scope_mismatch"
    for key in ("project_identity", "repository_identity"):
        if source.get(key) and source[key] != scope["project_id"]:
            return result, "reference_project_mismatch"
    if source.get("generation_id", scope["snapshot_id"]) != scope["snapshot_id"]:
        return result, "reference_snapshot_mismatch"
    if "resolved_version" in source and str(source.get("resolved_version") or "") != scope.get("version", ""):
        return result, "reference_version_mismatch"
    for key in ("path", "path_or_url", "project_doc_path", "source_path"):
        if source.get(key) and normalize_reference_path(str(source[key])) != normalize_reference_path(str(identity.get("canonical_path") or "")):
            return result, "reference_path_mismatch"
    file_snapshot_hash = str(evidence.get("project_doc_content_hash") or "").removeprefix("sha256:")
    for key in ("_source_snapshot_sha256", "project_doc_content_hash"):
        if source.get(key) and (
            not file_snapshot_hash
            or str(source[key]).removeprefix("sha256:") != file_snapshot_hash
        ):
            return result, "reference_content_mismatch"
    if (source.get("source_content_hash")
            and str(source["source_content_hash"]).removeprefix("sha256:")
                != identity.get("content_sha256")):
        return result, "reference_content_mismatch"
    start, end = evidence.get("char_start"), evidence.get("char_end")
    text = str(evidence.get("text") or "")
    if type(start) is not int or type(end) is not int or end-start != len(text):
        return result, "invalid_reference_window"
    span = (source["char_start"], source["char_end"]) if "char_start" in source and "char_end" in source else source.get("char_span") or ()
    if len(span) != 2 or any(type(pos) is not int for pos in span) or not start <= span[0] <= span[1] <= end:
        return result, "reference_window_mismatch"
    visible = evidence_text.strip()
    window = text[span[0]-start:span[1]-start]
    offset = window.find(visible)
    if not visible or offset < 0 or window.find(visible, offset+1) >= 0:
        return result, "reference_body_mismatch"
    visible_start = span[0] + offset
    plan = (source.get("_reference_plans") or {}).get(str(probe.get("query_text") or ""))
    if plan is not None and not _valid_reference_plan(plan, scope):
        return result, "reference_plan_mismatch"
    bindings = []
    seen = set()
    for item in (root, plan):
        for ref in (item or {}).get("references") or ():
            mention = ref["mention"]
            if mention["mention_id"] in seen or ref.get("role") != "source_locator":
                continue
            seen.add(mention["mention_id"])
            if ref.get("state") != "resolved":
                return result, str(ref.get("reason") or "unresolved_source_locator")
            if identity.get("document_id") not in ref.get("source_ids", ()):
                return result, "source_locator_mismatch"
            bindings.append({"mention_id": mention["mention_id"], "role": "source_locator", "field": "path", **identity})
    if plan is not None:
        body_question = reference_body_question(plan)
        if result.get("mode") == "exact_path":
            body_question = reference_body_question(root)
            result.pop("mode", None)
        roles = query_constraint_roles(body_question)
        original_roles = query_constraint_roles(reference_body_question(root))
        # Independent lookup coverage is query-local. Root source constraints
        # above remain mandatory, but a host facet need not repeat every root
        # symbol. Audited parent coverage still uses the existing parent terms.
        source_only_names = {ref["mention"]["text"].casefold() for ref in root["references"]
            if ref["role"] == "source_locator"} - set(original_roles.hard_exact) - set(original_roles.bound_subjects)
        parent_terms = [term for term in result.get("parent_exact_terms", ())
            if term.casefold() not in source_only_names]
        result.update(query_terms=list(documentation_query_terms(body_question)),
            exact_terms=list(roles.hard_exact), bound_subjects=list(roles.bound_subjects),
            parent_exact_terms=parent_terms, retrieval_anchors=list(roles.retrieval_anchors),
            reference_body_query=body_question)
    from .source_subject_binding import prepared_owner_rejection
    owner_reason = prepared_owner_rejection(evidence)
    if owner_reason is not None:
        return result, owner_reason
    owner = evidence.get("owner") or {}
    owner_text = str(owner.get("text") or "")
    if (owner_text and type(owner.get("scope_start")) is int and type(owner.get("scope_end")) is int
        and owner["scope_start"] <= visible_start <= visible_start+len(visible) <= owner["scope_end"]
        and owner.get("char_end", 0)-owner.get("char_start", 0) == len(owner_text)):
        result["bound_subject_context"] = owner_text
    for ref in (plan or root).get("references") or ():
        role, mention = ref["role"], ref["mention"]
        if role not in {"symbol_identity", "semantic_subject"}:
            continue
        match = re.search(technical_term_pattern(mention["text"], exact=True), visible, re.I)
        field, origin = "body", visible_start
        if match is None and role == "semantic_subject" and result.get("bound_subject_context"):
            match = re.search(technical_term_pattern(mention["text"], exact=True), owner_text, re.I)
            field, origin = "heading", owner["char_start"]
        if match:
            bindings.append({"mention_id": mention["mention_id"], "role": role, "field": field, **identity,
                "char_start": origin+match.start(), "char_end": origin+match.end()})
    result.update(reference_bindings=bindings, reference_visible_span=[visible_start, visible_start+len(visible)])
    return result, None

def unread_lines(start: int, end: int, visible: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Inclusive interval difference; a later quote never hides a gap."""
    if type(start) is not int or type(end) is not int or not 1 <= start <= end:
        raise ValueError("invalid line interval")
    cursor = start
    out = []
    for a, b in sorted(visible):
        if type(a) is not int or type(b) is not int or not 1 <= a <= b:
            raise ValueError("invalid visible interval")
        if b < cursor or a > end:
            continue
        if a > cursor:
            out.append((cursor, a - 1))
        cursor = max(cursor, b + 1)
        if cursor > end:
            break
    if cursor <= end:
        out.append((cursor, end))
    return out

def validate_model_visible_projection(
    payload: Any, *, snapshot: dict[str, dict[str, Any]], max_tokens: int,
    canonical_selection: SelectionDecision | AggregateMixedSelectionDecision | None = None,
) -> list[str]:
    errors: list[str] = []
    if not isinstance(payload, dict):
        return ["model-visible projection must be an object"]
    forbidden = sorted(_find_forbidden_keys(payload))
    if forbidden:
        errors.append("forbidden model-visible keys: " + ", ".join(forbidden))
    status, kind = payload.get("status"), payload.get("kind")
    if kind not in {"docs_answer", "docs_context", "patch_context"}:
        errors.append("invalid projection kind")
    if status not in {"ok", "truncated", "insufficient_evidence"}:
        errors.append("invalid projection status")
    limit = (
        min(INSUFFICIENT_EVIDENCE_MAX_TOKENS, max_tokens)
        if status == "insufficient_evidence"
        else max_tokens
    )
    actual = estimate_projection_tokens(payload)
    if payload.get("estimated_tokens") != actual or actual > limit:
        errors.append("projection estimate mismatch or budget exceeded")
    if (
        kind == "docs_context"
        and status in {"ok", "truncated"}
        and docs_context_budget_tokens(payload) > max_tokens
    ):
        errors.append("docs_context conservative budget exceeded")
    if status == "insufficient_evidence":
        transport = payload.get("support_envelope")
        transport_support: dict[str, Any] | None = None
        if transport is not None:
            try:
                transport_support = decode_support_envelope(transport)
            except ValueError as exc:
                errors.append(str(exc))
        for key, expected in (
            ("answer_supported", False),
            ("answer_available", False),
            ("support_status", "insufficient_evidence"),
        ):
            if key in payload and payload[key] != expected:
                errors.append(f"insufficient evidence has inconsistent {key}")
        if transport_support is not None:
            for key in _INSUFFICIENT_SUPPORT_KEYS:
                if key in payload and key in transport_support and payload[key] != transport_support[key]:
                    errors.append(f"support envelope {key} does not match the model summary")
        if payload.get("implementation_guidance") or payload.get("invariants") or payload.get("targets"):
            errors.append("insufficient evidence must not authorize edits")
        decision = (
            canonical_selection.selection_decision
            if isinstance(canonical_selection, AggregateMixedSelectionDecision)
            else canonical_selection
        )
        if decision is not None:
            visible_hash = payload.get("decision_hash")
            envelope_hash = (
                transport_support.get("decision_hash")
                if transport_support is not None else None
            )
            if visible_hash not in {None, decision.support_decision.decision_hash}:
                errors.append("projection decision hash does not match canonical selection")
            if envelope_hash not in {None, decision.support_decision.decision_hash}:
                errors.append("support envelope decision hash does not match canonical selection")
        return errors
    sources = payload.get("sources")
    if not isinstance(sources, list) or not sources:
        errors.append("successful projections require sources")
        return errors
    if kind in {"docs_answer", "docs_context"} and len(sources) > MAX_DOCS_SOURCES:
        errors.append(f"{kind} exceeds source limit")
    ids: set[str] = set()
    allowed_fields = (
        DOCS_SOURCE_FIELDS if kind == "docs_answer" else
        DOCS_CONTEXT_SOURCE_FIELDS if kind == "docs_context" else
        PATCH_SOURCE_FIELDS
    )
    for source in sources:
        if not isinstance(source, dict):
            errors.append("projection source must be an object")
            continue
        evidence_id = str(source.get("evidence_id") or "")
        bound = snapshot.get(evidence_id)
        if not evidence_id or not bound:
            errors.append("projection evidence_id does not resolve to the internal snapshot")
            continue
        expected = bound.get("projected_source")
        if not isinstance(expected, dict):
            errors.append("internal snapshot is missing its canonical projected source")
            continue
        optional = {"source_uri"} if kind == "docs_context" else set()
        missing = sorted(allowed_fields - set(source))
        unknown = sorted(set(source) - allowed_fields - optional)
        for key in missing:
            errors.append(f"projection source field is missing: {key}")
        if unknown:
            errors.append(
                "projection source contains unknown fields: " + ", ".join(unknown)
            )
        if set(expected) - optional != allowed_fields:
            errors.append("internal snapshot projected source schema is invalid")
        if (set(source) & optional != set(expected) & optional
            or source.get("source_uri") != expected.get("source_uri")):
            errors.append("projection source locator does not match the internal snapshot")
        if source.get("content_sha256") != expected.get("content_sha256"):
            errors.append("projection source hash does not match the internal snapshot")
        bound_source = bound.get("source")
        if (
            not isinstance(bound_source, dict)
            or _source_digest(bound_source) != expected.get("content_sha256")
        ):
            errors.append("internal snapshot hash does not match its source content")
        for key in sorted(allowed_fields & set(source) & set(expected)):
            if source.get(key) != expected.get(key):
                errors.append(f"projection source {key} does not match the internal snapshot")
        ids.add(evidence_id)
    if kind == "docs_answer":
        answer_refs = payload.get("answer_evidence_ids")
        if not isinstance(answer_refs, list) or not answer_refs or any(ref not in ids for ref in answer_refs):
            errors.append("docs_answer claims require valid evidence IDs")
        decision = (
            canonical_selection.selection_decision
            if isinstance(canonical_selection, AggregateMixedSelectionDecision)
            else canonical_selection
        )
        if decision is not None:
            if payload.get("answer_supported") is not True:
                errors.append("successful docs answer must be supported")
            assigned_witnesses = {
                assignment.evidence_id for assignment in decision.assignments
            }
            if ids != assigned_witnesses or set(answer_refs or ()) != assigned_witnesses:
                errors.append("model-visible evidence does not match aggregate assigned witnesses")
            visible_sources = {
                str(source.get("evidence_id") or ""): source
                for source in sources if isinstance(source, dict)
            }
            candidates_by_id = {
                candidate.stable_id: candidate
                for candidate in decision.selected_candidates
            }
            requirements_by_id = {
                requirement.requirement_id: requirement
                for requirement in decision.requirements
            }
            for assignment in decision.assignments:
                candidate = candidates_by_id.get(assignment.evidence_id)
                requirement = requirements_by_id.get(assignment.requirement_id)
                visible = visible_sources.get(assignment.evidence_id)
                if candidate is None or requirement is None or visible is None:
                    errors.append("model-visible assignment does not resolve to canonical evidence")
                    continue
                if not validate_assignment_binding(requirement, candidate, assignment):
                    errors.append("model-visible assignment failed unit proof revalidation")
                    continue
                unit = resolve_assignment_unit(candidate, assignment)
                if unit is not None and unit.text not in str(visible.get("snippet") or ""):
                    errors.append("model-visible assignment unit is absent from its cited source")
    if kind == "docs_context":
        if payload.get("answer_policy") != "cite_only":
            errors.append("docs_context answer policy must be cite_only")
        if payload.get("answer_supported") is not False or payload.get("answer_available") is not False:
            errors.append("docs_context must not claim a supported answer")
        if payload.get("edit_ready") is not False:
            errors.append("docs_context must not authorize edits")
        if payload.get("implementation_guidance") or payload.get("invariants") or payload.get("targets"):
            errors.append("docs_context must not contain edit guidance")
        if any(not str(source.get("project_identity") or "").strip() for source in sources):
            errors.append("docs_context sources require project identity")
        errors.extend(validate_context_selection_payload(payload, sources, snapshot=snapshot))
    if kind == "patch_context":
        mutation = payload.get("mutation_intent")
        if not isinstance(mutation, dict):
            errors.append("patch context requires a mutation intent contract")
        elif mutation.get("operation") != "none" and mutation.get("ready") is not True:
            errors.append("successful patch context requires operation-aware target readiness")
        if payload.get("edit_ready") is not bool(
            status in {"ok", "truncated"}
            and payload.get("mutation_ready") is True
            and not (payload.get("omitted_counts") or {}).get("mandatory_requirements")
            and payload.get("source_search_status") != "required"
        ):
            errors.append("patch context edit readiness is inconsistent with validated support")
        for item in _cited_patch_items(payload):
            refs = item.get("evidence_ids")
            if not isinstance(refs, list) or not refs or any(ref not in ids for ref in refs):
                errors.append("factual patch item has missing or unknown evidence_ids")
                break
    return errors

